        sca_drop_folder: 'You can drop an entire project folder — only dependency files are taken; everything else (including <code>node_modules</code>, <code>.git</code>, build output) is skipped automatically.',
        sca_url_ph: 'GitHub / GitLab repo link, or a link to a Dockerfile / package.json / lockfile (several allowed, space-separated)',
